  const explicitNames=(Array.isArray(shot?.assetNames)?shot.assetNames:[]).map(value=>typeof value==='string'?value:value?.name||value?.assetName||'').map(value=>String(value).trim().toLocaleLowerCase()).filter(Boolean);
