function promptValueText(value) {
  if (value == null || value === false) return '';
  if (Array.isArray(value)) return value.map(promptValueText).filter(Boolean).join('; ');
  if (typeof value === 'object') return Object.entries(value).map(([key, item]) => {
    const text = promptValueText(item);
    return text ? `${key}: ${text}` : '';
  }).filter(Boolean).join('; ');
  return String(value).replace(/\s+/g, ' ').trim();
}

function compileStoryboardImagePrompt(scene, visualBible, style, assets) {
  const compact = promptValueText;
  const assigned = (assets || []).map(asset => {
    const detail = compact(asset.description);
    const category = compact(asset.category || 'visual asset');
    // Asset expansions and rendering notes are written for design sheets. They
    // often contain sheet-only exclusions (for example, “no fox” on a garden
    // plate) that conflict with a later story scene. Use fixed identity facts;
    // the approved image and project art direction carry the visual design.
    return `${compact(asset.name)} (${category}): ${detail || 'match the selected reference design exactly'}`;
  }).join(' | ');
  const bible = typeof visualBible === 'string' ? visualBible : Object.entries(visualBible || {}).map(([key, value]) => `${key}: ${compact(value)}`).filter(row => !/^asset|reference/i.test(row)).join('; ');
  const action = compact(scene.action || scene.description || scene.prompt || scene.title || 'Show the planned story beat.');
  const shot = compact(scene.shot || scene.camera || scene.composition);
  const visualDirection = compact(scene.visualPrompt || scene.prompt);
  return [
    `Create one finished ${compact(style || visualBible?.style || 'anime cinematic')} film still with a clear focal subject and one coherent camera view. This frame belongs to a continuous story.`,
    `Scene ${scene.number || ''} — ${compact(scene.title || 'Untitled scene')}. Depict this exact story action: ${action}`,
    visualDirection ? `Storyboard image direction (preserve every specified action, subject, camera, setting, and visual detail): ${visualDirection}` : '',
    shot ? `Camera and composition: ${shot}` : visualDirection ? 'Follow the storyboard image direction exactly; do not replace its specified framing or visual details with generic alternatives.' : 'Choose a clear film composition that makes the action immediately readable; vary shot size and camera angle appropriately across the sequence.',
    bible ? `Project continuity bible (preserve these facts): ${bible}` : '',
    assigned ? `Continuity assignments (each name refers to one distinct reusable asset): preserve each assigned asset's defining silhouette, colors, markings, face, hair, wardrobe, and proportions. Keep character identity separate from uniform, vehicle, location, and prop design. Follow the scene action and camera direction above, placing each asset in a new pose and composition appropriate to this scene. Assigned assets: ${assigned}` : '',
    'Include only the characters, locations, vehicles, and props needed to show this scene action. Keep established design facts consistent with the continuity bible.',
    'Use one cinematic still with a single focal moment, frame-filling composition, and clear visual hierarchy.'
  ].filter(Boolean).join('\n');
}

function scenePromptEnhancementKey(scene, sourcePrompt, modelId, visualBible, references, assets) {
  return JSON.stringify({
    sceneId: scene.id,
    sourcePrompt,
    title: scene.title,
    description: scene.description,
    modelId,
    visualBible,
    refs: references.map(row => [row.assetId,row.referenceUrl,row.assignedAssetId,row.name,row.scope,row.sourceKind,row.role,row.roleName,row.assetName,row.assetCategory,row.assetDescription,row.assetVisualStyle,row.referenceObservations]),
    assets: assets.map(asset => [asset.id,asset.name,asset.category,asset.aliases,asset.description,asset.designExpansion,asset.visualStyle])
  });
}
function renumberScenePrompt(prompt, number) {
  return String(prompt || '').replace(/(^|\n)Scene\s+\d+\s+—\s+/u, `$1Scene ${number} — `);
}
