function compileStoryboardVideoPrompt({scene,project,language='English',transition='hard-cut',startScene,endScene,assets=[],references=[],videoMode='storyboard',separateReferences=false}) {
  const compact=promptValueText;
  const selectedLanguage=compact(language)||'English';
  const languageDirection=/^other(?:\b|\s*\()/i.test(selectedLanguage)
    ? 'Use the language explicitly requested in the scene prompt as the sole language for all spoken audio, including dialogue, narration, and lyrics, and for any explicitly requested visible writing. Do not code-switch. If no language is specified, use English.'
    : `Use ${selectedLanguage} exclusively for dialogue, narration, lyrics, and all spoken audio. Do not use another language or code-switch. Any explicitly requested visible writing must also use only ${selectedLanguage}.`;
  const openingScene=videoMode==='text'?scene:(startScene||scene);
  const sceneName=compact(openingScene?.title||scene?.title||'Untitled scene');
  const action=compact(openingScene?.description||openingScene?.action||scene?.description||scene?.action||sceneName);
  const visualBible=typeof project?.visualBible==='string'?project.visualBible:Object.entries(project?.visualBible||{}).map(([key,value])=>`${key}: ${compact(value)}`).filter(row=>!row.endsWith(': ')).join('; ');
  // Reuse visual cues from the approved storyboard prompt, but remove its
  // opening still-image directive so it cannot contradict video generation.
  const visualCues=compact(openingScene?.prompt||scene?.prompt)
    .replace(/^(?:create|generate|draw|show)\b[^.]*\b(?:film still|still image|single image|one image|one frame|still frame)\b[^.]*\.\s*/i,'')
    .replace(/^(?:this frame belongs to|this is one image from)\b[^.]*\.\s*/i,'')
    .trim();
  const endingAction=compact(endScene?.description||endScene?.action||endScene?.title||'');
  const endingVisualCues=compact(endScene?.prompt)
    .replace(/^(?:create|generate|draw|show)\b[^.]*\b(?:film still|still image|single image|one image|one frame|still frame)\b[^.]*\.\s*/i,'')
    .replace(/^(?:this frame belongs to|this is one image from)\b[^.]*\.\s*/i,'')
    .trim();
  const continuity=assets.map(asset=>`${compact(asset.name)} (${compact(asset.category||'asset')}): ${compact(asset.description)}${asset.designExpansion?` Design guidance: ${compact(asset.designExpansion)}`:''}${asset.visualStyle?` Style and palette: ${compact(asset.visualStyle)}`:''}`).filter(Boolean).join('\n');
  const referenceMap=references.map((frame,index)=>separateReferences?`<Picture ${index+1}> is ${compact(frame.assetName||frame.name||'visual asset')} (${compact(frame.referenceRole||'continuity')}): preserve the assigned design and identity; do not copy its pose or composition.`:`Reference ${index+1}, ${compact(frame.assetName||frame.name||'visual asset')} (${compact(frame.referenceRole||'continuity')}): preserve the assigned design and identity; do not copy its pose or composition.`).join('\n');
  const startCue=videoMode==='text'?'Create the shot from the written scene direction; no storyboard frame is attached.':`Use the approved storyboard keyframe for Scene ${startScene?compact(startScene.title):sceneName} as the exact opening frame. Preserve its visible identities, design, layout, and art style.`;
  const endingCue=transition==='flow'?(endScene?(videoMode==='text'?`Continue the text-generated shot into scene “${compact(endScene.title)}”. Required ending story action: ${endingAction||compact(endScene.title)}. End on that scene's described subjects, positions, environment, and composition${endingVisualCues?`; ending visual direction: ${endingVisualCues}`:''}. No storyboard ending image is attached.`:`Flow into the approved ending keyframe for Scene ${compact(endScene.title)}. Its required ending story action is: ${endingAction||compact(endScene.title)}. End on that scene's described subjects, positions, environment, and composition${endingVisualCues?`; ending visual direction: ${endingVisualCues}`:''}. Do not introduce a new beat after reaching it.`):'Animate continuously toward the next approved scene composition when one is supplied.'):'Finish on a stable composition suitable for a hard cut; do not morph into another scene.';
  const referenceDirection=separateReferences?`Automatically attached visual references, in matching order. Use the exact <Picture N> tag for each image when referring to it; preserve the assigned asset identity and design, but do not copy its pose or composition:\n${referenceMap}`:videoMode==='text'?`No separate visual-reference images are attached to this text-only workflow. Use these role-specific identity and design constraints as text guidance only:\n${referenceMap}`:`The selected video workflow cannot accept separate visual-reference images. Use the storyboard opening frame plus these role-specific identity and design constraints:\n${referenceMap}`;
  if(videoMode!=='text'){
    const storyboardEnding=transition==='flow'&&endScene
      ?`Continue naturally toward the selected ending keyframe for Scene “${compact(endScene.title)}”; do not add a new story beat.`
      :'Finish on a stable composition suitable for a hard cut.';
    return [
      `Create a single continuous shot for the anime series “${compact(project?.name||'')}”, scene “${sceneName}”.`,
      `Required opening story action: ${action}. Animate this action over time; do not return a still image.`,
      startCue,
      'Use the attached opening keyframe as the sole visual source of truth for the characters, setting, framing, style, and palette. Continue this same shot with subtle, coherent motion.',
      'Do not show character sheets, turnarounds, design boards, palettes, montages, cutaways, or additional scenes. Do not recreate any reference-library layout.',
      storyboardEnding,
      `${languageDirection} Add no subtitles, captions, or readable text unless the creator explicitly requests them.`
    ].filter(Boolean).join('\n\n');
  }
  return [
     `Create a moving video clip for the anime series “${compact(project?.name||'')}”, opening on scene “${sceneName}”.${endScene&&transition==='flow'?` The clip flows into scene “${compact(endScene.title)}”.`:''}`,
     `Required opening story action: ${action}. Animate this action over time; do not return a still image.`,
    startCue,
    visualCues?`Additional scene visual cues (use for subjects, setting, palette, and camera only): ${visualCues}`:'',
    visualBible?`Series art direction and canon: ${compact(visualBible)}`:'',
    continuity?`Continuity bible for this scene:\n${continuity}`:'',
    referenceMap?referenceDirection:'',
    'Keep motion readable and physically coherent, with restrained camera movement. Preserve the same characters, faces, clothing, insignia, props, vehicle silhouettes, colors, and proportions throughout; do not introduce new characters or change designs.',
    endingCue,
    `${languageDirection} Add no subtitles, captions, or readable text unless the creator explicitly requests them.`
  ].filter(Boolean).join('\n\n');
}
