  useEffect(()=>{if(!open)return;const onPointerDown=event=>{if(!wrap.current?.contains(event.target))setOpen(false);};const onKeyDown=event=>{if(event.key==='Escape')setOpen(false);};document.addEventListener('pointerdown',onPointerDown);document.addEventListener('keydown',onKeyDown);return()=>{document.removeEventListener('pointerdown',onPointerDown);document.removeEventListener('keydown',onKeyDown);};},[open]);
