function DependencySettings(){
  const [items,setItems]=useState([]),[install,setInstall]=useState(null),[error,setError]=useState('');
  const refresh=async()=>{try{const r=await fetch('/api/dependencies'),d=await r.json();if(!r.ok)throw new Error(d.error||'Could not read dependency status');setItems(d.dependencies||[]);setError('');}catch(e){setError(e.message);}};
  useEffect(()=>{refresh();const timer=setInterval(refresh,7000);return()=>clearInterval(timer);},[]);
  const installOllama=async()=>{setInstall({state:'Installing',message:'Starting Ollama setup'});try{const r=await fetch('/api/dependencies/ollama/install',{method:'POST',headers:{'content-type':'application/json'},body:'{}'}),job=await r.json();if(!r.ok)throw new Error(job.error);setInstall(job);const timer=setInterval(async()=>{try{const q=await fetch(`/api/dependencies/installs/${encodeURIComponent(job.id)}`),j=await q.json();setInstall(j);if(['Complete','Failed'].includes(j.state)){clearInterval(timer);await refresh();}}catch{}},1500);}catch(e){setInstall({state:'Failed',message:e.message});}};
  const prepareTts=async()=>{setInstall({state:'Preparing',message:'Loading or downloading the local English speech model'});try{const r=await fetch('/api/tts/prepare',{method:'POST',headers:{'content-type':'application/json'},body:'{}'}),d=await r.json();if(!r.ok)throw new Error(d.error);setInstall({state:d.state||'Preparing',message:d.message||'Speech model is preparing in the background'});const timer=setInterval(async()=>{try{const q=await fetch('/api/tts/status'),s=await q.json();setInstall({state:s.state||'Preparing',message:s.message||'Preparing speech model'});if(['Ready','Failed'].includes(s.state)){clearInterval(timer);await refresh();}}catch{}},1000);}catch(e){setInstall({state:'Failed',message:e.message});}};
  const configureComfy=async()=>{try{const r=await fetch('/api/dependencies/comfy/configure',{method:'POST',headers:{'content-type':'application/json'},body:'{}'}),d=await r.json();if(!r.ok)throw new Error(d.error);setInstall(d.alreadyRunning?{state:'Complete',message:'ComfyUI is already running. Local Flow saved the background launch settings for its next start.'}:{state:'Starting',message:`ComfyUI detected and launching in the background from ${d.cwd}`});await refresh();}catch(e){setInstall({state:'Failed',message:e.message});}};const configureOllama=async()=>{try{const r=await fetch('/api/dependencies/ollama/configure',{method:'POST',headers:{'content-type':'application/json'},body:'{}'}),d=await r.json();if(!r.ok)throw new Error(d.error);setInstall(d.alreadyRunning?{state:'Complete',message:'Ollama is already running. Local Flow saved the background launch settings for its next start.'}:{state:'Starting',message:'Ollama detected and launching in the background with Local Flow'});await refresh();}catch(e){setInstall({state:'Failed',message:e.message});}};const startService=async(id)=>{setInstall({state:'Starting',message:`Starting ${id} in the background`});try{const r=await fetch('/api/dependencies/start',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({service:id,force:true})}),d=await r.json();if(!r.ok)throw new Error(d.error);for(let attempt=0;attempt<660;attempt++){await new Promise(resolve=>setTimeout(resolve,1000));const q=await fetch('/api/dependencies'),status=await q.json(),item=status.dependencies?.find(row=>row.id===id);await refresh();if(item&&item.state!=='Starting'){setInstall({state:item.state==='Running'?'Complete':item.state==='Failed'?'Failed':'Complete',message:item.detail||`${id}: ${item.state}`});return;}}setInstall({state:'Failed',message:`${id} did not become ready within eleven minutes. Check the runtime log in Local Flow's data/logs folder.`});}catch(e){setInstall({state:'Failed',message:e.message});}};
  return <section className="settings-section dependency-section"><div className="settings-section-title"><div className="settings-section-icon"><HardDrive size={15}/></div><div><b>Runtime and dependency manager</b><small>FFmpeg ships with Local Flow. AI weights stay separate and selectable in Models.</small></div><button className="secondary-button" onClick={refresh}><RefreshCw size={13}/>Refresh</button></div><div className="dependency-grid">{items.map(x=><div className="dependency-row" key={x.id}><span className={`dependency-indicator ${['Running','Bundled','Installed','Available','Ready','Loading','Downloading','Generating'].includes(x.state)?'ready':''}`}/><div><b>{x.name}</b><small>{x.detail}</small></div><strong>{x.state}</strong>{x.id==='ollama'&&x.state==='Not detected'&&<button className="secondary-button" onClick={installOllama}>Install</button>}{x.id==='comfyui'&&x.canConfigure&&!['Running','Starting'].includes(x.state)&&<button className="secondary-button" onClick={configureComfy}>Use detected install</button>}{x.id==='ollama'&&x.canConfigure&&!['Running','Starting'].includes(x.state)&&<button className="secondary-button" onClick={configureOllama}>Use detected install</button>}{['comfyui','ollama'].includes(x.id)&&x.state!=='Running'&&(x.state==='Installed'||x.state==='Configured'||x.state==='Failed'||x.canConfigure)&&<button className="secondary-button" onClick={()=>startService(x.id)}>{x.state==='Failed'?'Retry background start':'Start in background'}</button>}{x.id==='tts'&&<button className="secondary-button" onClick={prepareTts} disabled={['Downloading','Loading','Generating'].includes(x.state)}>{['Downloading','Loading','Generating'].includes(x.state)?<LoaderCircle size={13} className="spin"/>:<AudioLines size={13}/>}Prepare speech</button>}</div>)}</div>{install&&<div className={`dependency-message ${install.state==='Failed'?'error':''}`}>{install.state}: {install.message}</div>}{error&&<div className="dependency-message error">{error}</div>}<div className="connection-help">When Local Flow opens, it detects and quietly starts configured ComfyUI and Ollama runtimes. Kokoro runs inside Local Flow, so it needs no separate TTS server. The first speech generation downloads its selected English model; Prepare speech downloads it early. Optional background preparation loads it when Local Flow opens. External OpenAI-compatible TTS services can also be configured to start hidden. Models stay outside the installer.</div></section>;
}


